enhanced_schema:
{
  "tables": [
    {
      "table_name": "proteins",
      "columns": [
        {
          "name": "protein_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each protein"
        },
        {
          "name": "protein_name",
          "type": "VARCHAR",
          "description": "Name of the protein"
        },
        {
          "name": "sequence",
          "type": "TEXT",
          "description": "Amino acid sequence of the protein"
        },
        {
          "name": "organism",
          "type": "VARCHAR",
          "description": "Organism from which the protein is derived"
        },
        {
          "name": "length",
          "type": "INTEGER",
          "description": "Length of the protein sequence"
        },
        {
          "name": "gene_name",
          "type": "VARCHAR",
          "description": "Gene associated with the protein"
        },
        {
          "name": "uniprot_id",
          "type": "VARCHAR",
          "description": "ID linking to UniProt database"
        },
        {
          "name": "structure_info",
          "type": "TEXT",
          "description": "Structural information of the protein"
        }
      ],
      "primary_key": [
        "protein_id"
      ]
    },
    {
      "table_name": "mutations",
      "columns": [
        {
          "name": "mutation_id",
          "type": "INTEGER",
          "description": "Unique identifier for each mutation"
        },
        {
          "name": "protein_id",
          "type": "VARCHAR",
          "description": "ID of the protein where the mutation occurs"
        },
        {
          "name": "position",
          "type": "INTEGER",
          "description": "Position of the mutation in the protein sequence"
        },
        {
          "name": "residue_ref",
          "type": "CHAR",
          "description": "Original amino acid residue"
        },
        {
          "name": "residue_alt",
          "type": "CHAR",
          "description": "Altered amino acid residue"
        },
        {
          "name": "score",
          "type": "FLOAT",
          "description": "Score indicating the impact of the mutation"
        },
        {
          "name": "prediction",
          "type": "VARCHAR",
          "description": "Prediction of the mutation's impact"
        },
        {
          "name": "functional_impact",
          "type": "VARCHAR",
          "description": "Functional consequence of the mutation"
        },
        {
          "name": "clinical_significance",
          "type": "VARCHAR",
          "description": "Clinical relevance of the mutation"
        },
        {
          "name": "db_snp_id",
          "type": "VARCHAR",
          "description": "Link to dbSNP database for mutation"
        }
      ],
      "primary_key": [
        "mutation_id"
      ],
      "foreign_keys": [
        {
          "column": "protein_id",
          "references": "proteins(protein_id)"
        }
      ]
    },
    {
      "table_name": "predictions",
      "columns": [
        {
          "name": "prediction_id",
          "type": "INTEGER",
          "description": "Unique identifier for each prediction outcome"
        },
        {
          "name": "mutation_id",
          "type": "INTEGER",
          "description": "Reference to the mutation being predicted"
        },
        {
          "name": "cutoff",
          "type": "FLOAT",
          "description": "Cutoff value used for prediction"
        },
        {
          "name": "score",
          "type": "FLOAT",
          "description": "Score related to the cutoff"
        },
        {
          "name": "result",
          "type": "VARCHAR",
          "description": "Result of the prediction"
        },
        {
          "name": "prediction_method",
          "type": "VARCHAR",
          "description": "Method used for the prediction"
        }
      ],
      "primary_key": [
        "prediction_id"
      ],
      "foreign_keys": [
        {
          "column": "mutation_id",
          "references": "mutations(mutation_id)"
        }
      ]
    },
    {
      "table_name": "sequence_clusters",
      "columns": [
        {
          "name": "cluster_id",
          "type": "INTEGER",
          "description": "Unique identifier for each sequence cluster"
        },
        {
          "name": "mutation_id",
          "type": "INTEGER",
          "description": "Reference to the mutation related to the cluster"
        },
        {
          "name": "num_sequences",
          "type": "INTEGER",
          "description": "Number of sequences in the cluster"
        },
        {
          "name": "num_clusters",
          "type": "INTEGER",
          "description": "Number of clusters"
        },
        {
          "name": "median_info",
          "type": "FLOAT",
          "description": "Median information score for the cluster"
        },
        {
          "name": "alignment_score",
          "type": "FLOAT",
          "description": "Quality of sequence alignment within the cluster"
        }
      ],
      "primary_key": [
        "cluster_id"
      ],
      "foreign_keys": [
        {
          "column": "mutation_id",
          "references": "mutations(mutation_id)"
        }
      ]
    },
    {
      "table_name": "users",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user"
        },
        {
          "name": "user_name",
          "type": "VARCHAR",
          "description": "Full name of the user"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "Email address of the user"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user (e.g., researcher, analyst)"
        },
        {
          "name": "organization",
          "type": "VARCHAR",
          "description": "Organization the user belongs to"
        },
        {
          "name": "last_login",
          "type": "DATETIME",
          "description": "Last login time of the user"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "tools",
      "columns": [
        {
          "name": "tool_id",
          "type": "INTEGER",
          "description": "Unique identifier for each tool"
        },
        {
          "name": "name",
          "type": "VARCHAR",
          "description": "Name of the tool"
        },
        {
          "name": "version",
          "type": "VARCHAR",
          "description": "Version of the tool"
        },
        {
          "name": "developer",
          "type": "VARCHAR",
          "description": "Developer of the tool"
        },
        {
          "name": "description",
          "type": "TEXT",
          "description": "Description of the tool"
        },
        {
          "name": "tool_type",
          "type": "VARCHAR",
          "description": "Category of the tool"
        }
      ],
      "primary_key": [
        "tool_id"
      ]
    },
    {
      "table_name": "mutation_annotations",
      "columns": [
        {
          "name": "annotation_id",
          "type": "INTEGER",
          "description": "Unique identifier for each annotation"
        },
        {
          "name": "mutation_id",
          "type": "INTEGER",
          "description": "Reference to the mutation being annotated"
        },
        {
          "name": "annotation_source",
          "type": "VARCHAR",
          "description": "Source of the annotation"
        },
        {
          "name": "annotation_type",
          "type": "VARCHAR",
          "description": "Type of annotation"
        },
        {
          "name": "annotation_details",
          "type": "TEXT",
          "description": "Detailed information of the annotation"
        },
        {
          "name": "date_added",
          "type": "DATE",
          "description": "Date the annotation was added"
        }
      ],
      "primary_key": [
        "annotation_id"
      ],
      "foreign_keys": [
        {
          "column": "mutation_id",
          "references": "mutations(mutation_id)"
        }
      ]
    }
  ]
}
